def completar_departamento(apps, schema_editor):
    """Las comisiones existentes (todas de optativas) informan en el departamento que las dicta."""
    Comision = apps.get_model('planes', 'Comision')
    for c in Comision.objects.select_related('materia_optativa', 'carrera'):
        dictante = c.materia_optativa.departamento if c.materia_optativa_id else ''
        c.departamento = c.carrera.departamento if dictante in ('', 'Externo') else dictante
        c.save(update_fields=['departamento'])


